  1 | import { useCallback, useRef, useState, useEffect } from "react";
  2 | import { usePlayerWithAudio } from "./hooks/usePlayerWithAudio";
  3 | import { useMetadata } from "./hooks/useMetadata";
  4 | import { useTauri } from "./hooks/useTauri";
  5 | import {
  6 |   TitleBar,
  7 |   Playlist,
  8 |   PlayerControls,
  9 |   ProgressBar,
 10 |   StatusBar,
 11 |   DriveBrowser,
 12 | } from "./components";
 13 | import type { Track } from "./types";
 14 | 
 15 | function App() {
 16 |   const {
 17 |     state,
 18 |     play,
 19 |     pause,
 20 |     next,
 21 |     prev,
 22 |     seek,
 23 |     setVolume,
 24 |     addTrack,
 25 |     toggleShuffle,
 26 |     reorderPlaylist,
 27 |   } = usePlayerWithAudio([]);
 28 | 
 29 |   const { processFiles } = useMetadata();
 30 |   const {
 31 |     state: tauriState,
 32 |     openFilePicker,
 33 |     filePathToUrl,
 34 |     sendNotification,
 35 |     registerShortcuts,
 36 |   } = useTauri();
 37 | 
 38 |   const [isLoading, setIsLoading] = useState(false);
 39 |   const [showDrive, setShowDrive] = useState(false);
 40 | 
 41 |   const fileInputRef = useRef<HTMLInputElement>(null);
 42 | 
 43 |   // Registra atalhos de teclado (Media Session API + Tauri global shortcuts)
 44 |   useEffect(() => {
 45 |     const cleanup = registerShortcuts({
 46 |       MediaPlayPause: () => (state.isPlaying ? pause() : play()),
 47 |       MediaNextTrack: () => next(),
 48 |       MediaPrevTrack: () => prev(),
 49 |       MediaStop: () => pause(),
 50 |     });
 51 | 
 52 |     return () => {
 53 |       cleanup.then((fn) => fn());
 54 |     };
 55 |   }, [registerShortcuts, state.isPlaying, pause, play, next, prev]);
 56 | 
 57 |   // Media Session API (navegador)
 58 |   useEffect(() => {
 59 |     if (!("mediaSession" in navigator)) return;
 60 | 
 61 |     navigator.mediaSession.metadata = new MediaMetadata({
 62 |       title: state.currentTrack?.title ?? "Llama Player",
 63 |       artist: state.currentTrack?.artist ?? undefined,
 64 |       album: state.currentTrack?.album ?? undefined,
 65 |     });
 66 | 
 67 |     navigator.mediaSession.setActionHandler("play", () => play());
 68 |     navigator.mediaSession.setActionHandler("pause", () => pause());
 69 |     navigator.mediaSession.setActionHandler("nexttrack", () => next());
 70 |     navigator.mediaSession.setActionHandler("previoustrack", () => prev());
 71 |   }, [state.currentTrack, play, pause, next, prev]);
 72 | 
 73 |   // Notificação ao trocar de música
 74 |   useEffect(() => {
 75 |     if (state.currentTrack && state.isPlaying) {
 76 |       sendNotification(
 77 |         `▶ ${state.currentTrack.title}`,
 78 |         state.currentTrack.artist
 79 |           ? `Por ${state.currentTrack.artist}`
 80 |           : undefined
 81 |       );
 82 |     }
 83 |   }, [state.currentTrack?.id, state.isPlaying]); // eslint-disable-line react-hooks/exhaustive-deps
 84 | 
 85 |   const handleSelectTrack = (track: Track) => {
 86 |     play(track);
 87 |   };
 88 | 
 89 |   const handleOpenFile = async () => {
 90 |     if (tauriState.isTauri) {
 91 |       // Usa file picker nativo do Tauri
 92 |       setIsLoading(true);
 93 |       try {
 94 |         const paths = await openFilePicker();
 95 |         if (!paths || paths.length === 0) return;
 96 | 
 97 |         // Converte paths para File objects (via fetch do asset protocol)
 98 |         const tracks: Track[] = [];
 99 |         for (const path of paths) {
100 |           const url = await filePathToUrl(path);
101 |           const name = path.split(/[/\\]/).pop() || path;
102 |           tracks.push({
103 |             id: `local-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
104 |             title: name.replace(/\.[^/.]+$/, ""),
105 |             duration: 0,
106 |             src: url,
107 |           });
108 |         }
109 | 
110 |         for (const track of tracks) {
111 |           addTrack(track);
112 |         }
113 | 
114 |         if (!state.currentTrack && tracks.length > 0) {
115 |           play(tracks[0]);
116 |         }
117 |       } catch (err) {
118 |         console.error("[Llama Player] Erro ao abrir arquivos:", err);
119 |       } finally {
120 |         setIsLoading(false);
121 |       }
122 |     } else {
123 |       // Fallback: input file HTML
124 |       fileInputRef.current?.click();
125 |     }
126 |   };
127 | 
128 |   const handleFileChange = useCallback(
129 |     async (e: React.ChangeEvent<HTMLInputElement>) => {
130 |       const files = e.target.files;
131 |       if (!files || files.length === 0) return;
132 | 
133 |       setIsLoading(true);
134 | 
135 |       try {
136 |         const fileArray = Array.from(files);
137 |         const tracks = await processFiles(fileArray);
138 | 
139 |         for (const track of tracks) {
140 |           addTrack(track);
141 |         }
142 | 
143 |         // If nothing is playing, start with the first track
144 |         if (!state.currentTrack && tracks.length > 0) {
145 |           play(tracks[0]);
146 |         }
147 |       } catch (err) {
148 |         console.error("[Llama Player] Erro ao processar arquivos:", err);
149 |       } finally {
150 |         setIsLoading(false);
151 |       }
152 | 
153 |       // Reset input so the same file can be selected again
154 |       e.target.value = "";
155 |     },
156 |     [processFiles, addTrack, state.currentTrack, play]
157 |   );
158 | 
159 |   const handleDropFiles = useCallback(
160 |     async (files: FileList) => {
161 |       setIsLoading(true);
162 |       try {
163 |         const fileArray = Array.from(files);
164 |         const tracks = await processFiles(fileArray);
165 |         for (const track of tracks) {
166 |           addTrack(track);
167 |         }
168 |         if (!state.currentTrack && tracks.length > 0) {
169 |           play(tracks[0]);
170 |         }
171 |       } catch (err) {
172 |         console.error("[Llama Player] Erro ao processar arquivos arrastados:", err);
173 |       } finally {
174 |         setIsLoading(false);
175 |       }
176 |     },
177 |     [processFiles, addTrack, state.currentTrack, play]
178 |   );
179 | 
180 |   const handleAddDriveTracks = useCallback(
181 |     (tracks: Track[]) => {
182 |       for (const track of tracks) {
183 |         addTrack(track);
184 |       }
185 |       if (!state.currentTrack && tracks.length > 0) {
186 |         play(tracks[0]);
187 |       }
188 |     },
189 |     [addTrack, state.currentTrack, play]
190 |   );
191 | 
192 |   return (
193 |     <div className="app">
194 |       <TitleBar />
195 | 
196 |       <main className="main-content">
197 |         <div className="toolbar">
198 |           <button
199 |             className="toolbar-btn"
200 |             onClick={handleOpenFile}
201 |             disabled={isLoading}
202 |             title="Abrir arquivo de áudio local"
203 |           >
204 |             {isLoading ? "⏳ Lendo metadados..." : "📂 Arquivo local"}
205 |           </button>
206 |           <input
207 |             ref={fileInputRef}
208 |             type="file"
209 |             accept="audio/*"
210 |             multiple
211 |             style={{ display: "none" }}
212 |             onChange={handleFileChange}
213 |           />
214 |           <button
215 |             className={`toolbar-btn ${showDrive ? "toolbar-btn-active" : ""}`}
216 |             onClick={() => setShowDrive((v) => !v)}
217 |             title="Google Drive"
218 |           >
219 |             ☁️ Drive
220 |           </button>
221 |         </div>
222 | 
223 |         {showDrive && (
224 |           <DriveBrowser onAddTracks={handleAddDriveTracks} />
225 |         )}
226 | 
227 |         <Playlist
228 |           tracks={state.playlist}
229 |           currentTrackId={state.currentTrack?.id ?? null}
230 |           isPlaying={state.isPlaying}
231 |           onSelectTrack={handleSelectTrack}
232 |           onReorderPlaylist={reorderPlaylist}
233 |           onDropFiles={handleDropFiles}
234 |         />
235 | 
236 |         <PlayerControls
237 |           currentTrack={state.currentTrack}
238 |           isPlaying={state.isPlaying}
239 |           isShuffled={state.isShuffled}
240 |           onPlay={() => play()}
241 |           onPause={pause}
242 |           onNext={next}
243 |           onPrev={prev}
244 |           onToggleShuffle={toggleShuffle}
245 |         />
246 | 
247 |         <ProgressBar
248 |           currentTime={state.currentTime}
249 |           duration={state.duration}
250 |           onSeek={seek}
251 |         />
252 |       </main>
253 | 
254 |       <StatusBar
255 |         isPlaying={state.isPlaying}
256 |         volume={state.volume}
257 |         onVolumeChange={setVolume}
258 |       />
259 |     </div>
260 |   );
261 | }
262 | 
263 | export default App;
